"""Shared natural intent identity, independent from policy and authority validation."""

import hashlib
import json
from dataclasses import dataclass
from datetime import date
from uuid import UUID


@dataclass(frozen=True, slots=True)
class BusinessIntent:
    """Natural identity excludes message/proposal UUIDs regenerated by retries."""

    engagement: UUID
    playbook: UUID
    period_start: date
    period_end: date
    amendment: int
    step_key: str
    action_kind: str
    occurrence: int = 0

    def key(self, tenant: UUID) -> str:
        """JCS of a fixed primitive tuple (no floats or unordered dictionaries)."""
        values = [
            str(tenant),
            str(self.engagement),
            str(self.playbook),
            self.period_start.isoformat(),
            self.period_end.isoformat(),
            self.amendment,
            self.step_key,
            self.action_kind,
            self.occurrence,
        ]
        encoded = json.dumps(values, ensure_ascii=False, separators=(",", ":"))
        return hashlib.sha256(encoded.encode()).hexdigest()
